export type ImageAsset = {
  src: string;
  alt: string;
  objectPosition?: string;
  cropDesktop?: string;
  cropTablet?: string;
  cropMobile?: string;
  orientation?: "portrait" | "landscape" | "square";
  width?: number;
  height?: number;
  focalPoint?: { x: number; y: number };
  event?: string;
  importance?: "supporting" | "standard" | "feature";
  layoutRole?: "portrait" | "landscape" | "wide" | "panoramic" | "detail" | "feature";
};

export type StoryImage = ImageAsset & {
  importance?: "supporting" | "standard" | "feature";
  layoutRole?: "portrait" | "landscape" | "wide" | "panoramic" | "detail" | "feature";
  event?: string;
  selectionReason?: string;
};

export type StoryModule = {
  id: string;
  module: "B" | "C" | "D" | "E" | "F" | "G" | "H" | "I" | "J" | "K";
  intent: string;
  images: StoryImage[];
};

export type OpeningTriptych = {
  module: "A";
  left: StoryImage & { selectionReason?: string };
  center: StoryImage & { selectionReason?: string };
  right: StoryImage & { selectionReason?: string };
};

export type StoryFunction = {
  id: string;
  label: string;
  order: number;
  layoutPattern?: "A" | "B" | "C" | "D" | "E" | "F" | "G" | "H";
  images: StoryImage[];
  modules?: StoryModule[];
};

export type CoupleStoryManifest = {
  slug: string;
  storyTier?: "featured-complete" | "developed" | "limited-archive";
  quote: string;
  openingTriptych?: OpeningTriptych;
  soundtrack?: {
    title: string;
    artist?: string;
    localSrc?: string;
    expectedLocalSrc?: string;
    referenceUrl?: string;
    highlightStartSeconds: number;
    defaultVolume?: number;
    loopFromHighlight?: boolean;
  };
  film?: {
    poster?: ImageAsset;
    localVideoUrl?: string;
    sourceUrl?: string;
    title?: string;
  };
  functions: StoryFunction[];
  closingImage?: StoryImage;
};

export type MemorySlide = {
  id: string;
  dominantTone?: string;
} & ImageAsset;

export type Story = {
  slug: string;
  coupleName: string;
  category: "Wedding Story" | "Pre-Wedding" | "Photo + Film Story";
  location: string;
  intro: string;
  note: string;
  mood: string;
  cover: ImageAsset;
  hero: ImageAsset;
  gallery: ImageAsset[];
  events: string[];
  filmSlug?: string;
};

export type Film = {
  slug: string;
  coupleName: string;
  title: string;
  type: "Teaser" | "Highlight Film" | "Same-Day Edit" | "Pre-Wedding Film" | "Reel";
  description: string;
  poster: ImageAsset;
  youtubeUrl?: string;
  localVideoUrl?: string;
};

export type EventWork = {
  slug: string;
  label: string;
  title: string;
  coupleName: string;
  copy: string;
  image: ImageAsset;
};

